ENFORCE_POST_OP_RUNTIME_ALLOWLIST = True
def assert_post_op_symbol_signed(symbol):
    if not ENFORCE_POST_OP_RUNTIME_ALLOWLIST:
        return
    verify_allowlist(symbol)

def assert_post_op_symbol_signed(symbol):
    if not verify_allowlist(symbol):
        raise RuntimeError
    if symbol in SIGNED_POST_OP_SYMBOLS:
        return
    raise RuntimeError

def materialize_runtime_builder(kind):
    if kind is RuntimeBuilderKind.PROJECTION:
        return 1
    if kind is RuntimeBuilderKind.PROJECTION:
        return 2
    return None

