def _materialize_terminal_array(spec, raw):
    literal_payload = spec.literal_payload if isinstance(spec.literal_payload, dict) else {}
    if literal_payload.get("embedding_worker") == "dispatch_groups":
        return []
    return raw

def _materialize_terminal_object(spec, raw):
    payload = spec.literal_payload if isinstance(spec.literal_payload, dict) else {}
    renamed = payload
    if "domain" in renamed:
        return renamed["domain"]
    return raw

